{
  "name": "opencode-vision-paste",
  "version": "0.3.0",
  "description": "OpenCode plugin: intercept pasted images → local VL API analysis → replace with text",
  "type": "module",
  "main": "vision-paste.mjs",
  "bin": {
    "opencode-vision-paste": "cli.mjs"
  },
  "files": [
    "vision-paste.mjs",
    "cli.mjs",
    "docker-compose.yml",
    "examples/"
  ],
  "engines": {
    "node": ">=18",
    "opencode": ">=0.1.0"
  },
  "scripts": {
    "test": "node --check vision-paste.mjs"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "vision",
    "qwen-vl",
    "image-analysis",
    "vl",
    "multimodal"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/wsaaaqqq/opencode-vision-paste.git"
  },
  "bugs": {
    "url": "https://github.com/wsaaaqqq/opencode-vision-paste/issues"
  },
  "homepage": "https://github.com/wsaaaqqq/opencode-vision-paste#readme",
  "author": "",
  "dependencies": {
    "commander": "^14.0.3"
  }
}
